import json
import os

class TaskManager:
    def __init__(self, storage_file='tasks.json'):
        self.storage_file = storage_file
        self.tasks = self.load_tasks()

    def load_tasks(self):
        if os.path.exists(self.storage_file):
            try:
                with open(self.storage_file, 'r') as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return []
        return []

    def save_tasks(self):
        try:
            with open(self.storage_file, 'w') as f:
                json.dump(self.tasks, f, indent=4)
        except IOError as e:
            print(f"Error saving tasks: {e}")

    def add_task(self, description):
        task = {
            'id': len(self.tasks) + 1,
            'description': description,
            'completed': False
        }
        self.tasks.append(task)
        self.save_tasks()
        return task

    def list_tasks(self):
        return self.tasks

    def complete_task(self, task_id):
        for task in self.tasks:
            if task['id'] == task_id:
                task['completed'] = True
                self.save_tasks()
                return True
        return False

    def delete_task(self, task_id):
        for i, task in enumerate(self.tasks):
            if task['id'] == task_id:
                del self.tasks[i]
                # Re-index tasks to keep IDs sequential (optional but cleaner for this simple app)
                for j, t in enumerate(self.tasks):
                    t['id'] = j + 1
                self.save_tasks()
                return True
        return False

from task_manager_logic import TaskManager

class TaskCLI:
    def __init__(self):
        self.manager = TaskManager()

    def run(self):
        print("Welcome to the Simple Task Manager!")
        print("Commands: add <desc>, list, complete <id>, delete <id>, quit")

        while True:
            try:
                user_input = input("\n> ").strip()
                if not user_input:
                    continue

                parts = user_input.split(maxsplit=1)
                command = parts[0].lower()
                args = parts[1] if len(parts) > 1 else None

                if command == 'quit':
                    print("Goodbye!")
                    break
                elif command == 'add':
                    if args:
                        self.manager.add_task(args)
                        print(f"Task added: {args}")
                    else:
                        print("Error: Please provide a task description.")
                elif command == 'list':
                    tasks = self.manager.list_tasks()
                    if not tasks:
                        print("No tasks found.")
                    else:
                        for task in tasks:
                            status = "[x]" if task['completed'] else "[ ]"
                            print(f"{task['id']}. {status} {task['description']}")
                elif command == 'complete':
                    if args and args.isdigit():
                        if self.manager.complete_task(int(args)):
                            print(f"Task {args} marked as completed.")
                        else:
                            print(f"Error: Task {args} not found.")
                    else:
                        print("Error: Please provide a valid task ID.")
                elif command == 'delete':
                    if args and args.isdigit():
                        if self.manager.delete_task(int(args)):
                            print(f"Task {args} deleted.")
                        else:
                            print(f"Error: Task {args} not found.")
                    else:
                        print("Error: Please provide a valid task ID.")
                else:
                    print("Unknown command. Available commands: add, list, complete, delete, quit")
            except EOFError:
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

from task_manager_cli import TaskCLI

def main():
    cli = TaskCLI()
    cli.run()

if __name__ == "__main__":
    main()

